#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# Task 470: обновление системного промта kip8test (post-Task 470
# ПЕРЕНОС — зеркальная фиксация переноса в kip8).
import io
import sys

PATH = 'Системный_промт_для_приложения_КИПиА.md'
with io.open(PATH, encoding='utf-8') as f:
    src = f.read()

CUR_MARK = '> **Версия документа:** 2026-10-03 (post-Task 469 ПЕРЕНОС'
PREV_MARK = '> **Версия документа (предыдущая):**'

NEW_LINE3 = '> **Версия документа:** 2026-10-03 (post-Task 470 ПЕРЕНОС: Task 470 перенесён из kip8test@059dad05 в боевой kip8 ОДНИМ инкрементом SW kipia-v505→v506 — КЛИЕНТ-ONLY, серверных шагов НЕТ (Apps Script не менялся); заявка: «В таблице плановых мероприятий, в конце сокращённого слова месяца ноября "Ноя" поставь точку. К группе мероприятий в конце месяца добавь мероприятие "Работы на следующий месяц", и ниже в таблице создай новую группу мероприятий "На текущий месяц", и добавь в эту группу новое мероприятие "Работы на месяц".»): СУТЬ (таблица Task 460 / отметки Task 463-464 / раскладка Task 468): (1) шапка месяцев — «Ноя» → «Ноя.» (точка у сокращения, как у прочих сокращённых месяцев; «Май» — полное слово, БЕЗ точки — не тронуто); (2) в группу «В конце месяца» добавлено мероприятие «Работы на следующий месяц» (последней строкой группы, 5 → 6); (3) НОВАЯ группа «На текущий месяц» (pe-group colspan 13, формат групп Task 460) с мероприятием «Работы на месяц» (единственное в группе) — внизу таблицы; итого 8 → 10 строк мероприятий, 96 → 120 пустых ячеек td.pe-m; отметки Task 463 работают по НАИМЕНОВАНИЮ из DOM (один источник истины — разметка; совпадение с архивом по точной строке) — новые строки АВТОМАТИЧЕСКИ кликабельны без правок JS: клик по ячейке → диалог «Отметка выполнения» («Работы на месяц — Ноябрь 2026», дата по умолчанию сегодняшняя). НЕ ТРОНУТЫ: раскладка Task 468 (таблица влево по контенту + окно «Описание раздела» справа), окно описания Task 469 (лид «Периодические работы на участке КИП ИОС…» + 4 пункта), мобильный вид Task 464 (один видимый месяц: теперь 10 строк × 1 = 10 ячеек), JS/CSS. ПЕРЕНОС: scripts/task470-transfer.py в kip8 (де-изоляция ×15, «дифф диффов»: репо-дифф 59 == эталону kip8test@3150dba9↔kip8@c89dd32, дифф задач 31 идентичен; .gs не тронуты — синхронны, Code.gs kip8-версия жива); тесты kip8 5334/0 = паритет 5328 + 6 task344 (маппинг v694→v506 (522)/v695→v507 (123)/негатив партии v693→v505 (1: test-task470)/негатив 469 v692→v504 (1)/негатив 468 v691→v503 (1)/негатив 467 v690→v502 (1)/негативы 466 v689→v501 (2)/исторические; IMAGE_CACHE_VERSION kipia-images-test-v3 → kipia-images-v3; test-task344 v505→v506; run-all +470); SMOKE task470-smoke-k8.py 22/22 (порт 8997, ключи без префикса: «Ноя.»/3 группы/10 строк/иконки 120 ячеек/диалог новой строки/раскладка 468 жива/лид 469 жив/1100 колонка/375 мобайл 10 ячеек; 0 JS). ПОДВОДНЫЕ КАМНИ: (а) перенос-скрипт ОДНОРАЗОВЫЙ — повторный прогон вставил ДУБЛЬ require в run-all.js kip8 (известный паттерн 466/467; дубль убран, при повторе — git checkout затронутого файла); (б) НОВЫЙ: комментарий Task 470 в sw.js kip8 НЕ должен РАЗРЫВАТЬ строку «Работы на следующий месяц» переносом — тест ассертит целую фразу (первый прогон 5333/1; фикс — перенос слова «месяц» на строку с фразой целиком); (в) test-task461.js — окно истории sw.js 2500 → 3050 (комментарий 470 отодвинул комментарий 461). БАМП: task470-bump-tests.py (guards v694→v695 (123)/ассерты v693→v694 (519), 154 файла) — test-task470.js писался ПОСЛЕ бампа с финальной v694. Тесты kip8test 5328/0 (178 файлов; НОВЫЙ test-task470.js ×24: «Ноя.» ×4 (точка/без точки нет/прочие месяцы/канон 12), «Работы на следующий месяц» ×4 (строка/структура 13 ячеек/внутри группы последней/после ППР), группа «На текущий месяц» ×5 (заголовок/ниже групп/одно мероприятие/структура/последняя строка), итоговая структура ×4 (10 pe-row/3 pe-group/120 ячеек/перечень-порядок), JS не тронут ×3 (PlanEventsData/_cellInfo из DOM/делегированный клик/464+468 живы), SW ×4 (v694/v693 нет/комментарий 470/IMAGE_CACHE)); адаптация test-task460 (MONTHS_SAMPLE Ноя./GROUPS_SAMPLE +2/10 мероприятий/120 ячеек/3 группы/новая группа в ассертах), test-task461 (окно 3050), test-task463/464 (96 → 120). Браузер task470-browser-check.py 32/32 (порт 8999: A 1600 — шапка/группы/порядок/структура/иконки 120/раскладка 468; B клики по новым строкам — диалог «Работы на месяц — Ноябрь 2026» + дата сегодня + «Отмена» + 0 запросов mark, диалог «Работы на следующий месяц — Ноябрь 2026»; C 1100 колонка; D 375 — Task 464 жив, 10 видимых ячеек; 0 JS; подводный камень: «active» диалога добавляется через requestAnimationFrame — после клика пауза 300мс). VLM ×2 (десктоп: «Ноя.» с точкой, 3 группы, новые строки на месте, без дефектов; мобайл: полоса месяца, все строки видны, без обрезок). Артефакты download/kip8test-task470/ (×5 png) + download/kip8-task470/ (smoke ×1 png). DEPLOY-Task470-plan-events-november-dot-new-rows.md (КЛИЕНТ-ONLY — серверных шагов НЕТ; скопирован в kip8). ТЕКУЩЕЕ СОСТОЯНИЕ: kip8test @059dad05 SW `kipia-test-v694` (guard v695), тесты 5328/0; kip8 @62dd6d0 SW `kipia-v506` (guard v507), тесты 5334/0 (паритет + 6 task344) — Task 470 выкачан в ОБОИХ репо, открытых хвостов нет; десктопы — CI-автосинк. СЛЕДУЮЩИЙ НОМЕР ЗАДАЧИ: 471 (в обоих репо).'

if CUR_MARK not in src:
    print('ОШИБКА: не найдена строка версии post-469-ПЕРЕНОС')
    sys.exit(1)

n_prev_before = src.count(PREV_MARK)

i3 = src.index(CUR_MARK)
i3end = src.index('\n', i3)
old_line3 = src[i3:i3end]

# (а) удалить самую старую строку «предыдущая» (храним 2 последних)
if src.count(PREV_MARK) > 2:
    iprev = src.rindex(PREV_MARK)
    iprev_end = src.index('\n', iprev)
    src = src[:iprev] + src[iprev_end + 1:]

# (б) строка 3 → новая версия + «предыдущая» из старой строки 3
new_prev = PREV_MARK + ' ' + old_line3[len('> **Версия документа:** '):]
src = src[:i3] + NEW_LINE3 + '\n' + new_prev + src[i3end:]

# (в) «Текущая версия кэша» v693 → v694
old_cache = '> **Текущая версия кэша:** `kipia-test-v693`'
new_cache = '> **Текущая версия кэша:** `kipia-test-v694`'
if old_cache not in src:
    print('ОШИБКА: не найдена строка текущей версии кэша')
    sys.exit(1)
src = src.replace(old_cache, new_cache, 1)

# (г) строка «Инкрементируй» — следующие версии
old_inc = 'Формат: `kipia-test-v693` → `kipia-test-v694` (для kip8test) или `kipia-v504` → `kipia-v505` (для kip8)'
new_inc = 'Формат: `kipia-test-v694` → `kipia-test-v695` (для kip8test) или `kipia-v505` → `kipia-v506` (для kip8)'
if old_inc not in src:
    print('ОШИБКА: не найдена строка «Инкрементируй»')
    sys.exit(1)
src = src.replace(old_inc, new_inc, 1)

# (д) ожидание тестов 5304/5310 → 5328/5334
old_exp = '# Ожидается: 5304 passed, 0 failed (kip8test; в kip8 — 5310 passed, 0 failed)'
new_exp = '# Ожидается: 5328 passed, 0 failed (kip8test; в kip8 — 5334 passed, 0 failed)'
if old_exp not in src:
    print('ОШИБКА: не найдена строка ожидания тестов')
    sys.exit(1)
src = src.replace(old_exp, new_exp, 1)

# (е) контроль
assert src.count(NEW_LINE3) == 1
assert src.count(PREV_MARK) <= n_prev_before + 1

with io.open(PATH, 'w', encoding='utf-8') as f:
    f.write(src)
print('OK: промт kip8test обновлён до post-Task 470 ПЕРЕНОС')
print('  предыдущих строк: %d (было %d)' % (src.count(PREV_MARK), n_prev_before))
